begin;
create table public.appropriation_changes(id uuid primary key default gen_random_uuid(),appropriation_id uuid not null references public.appropriations,before_amount bigint not null,after_amount bigint not null,basis text not null,actor uuid not null references public.profiles(auth_user_id),created_at timestamptz not null default now());
create index appropriation_changes_parent_idx on public.appropriation_changes(appropriation_id);
create index appropriation_changes_actor_idx on public.appropriation_changes(actor);
alter table public.appropriation_changes enable row level security;
revoke all on public.appropriation_changes from anon,authenticated;
grant select on public.appropriation_changes to authenticated;
create policy appropriation_changes_read on public.appropriation_changes for select to authenticated using(private.treasury_read());
create function private.freeze_record() returns trigger language plpgsql set search_path='' as $$begin raise exception 'immutable_record_create_correction_instead';end;$$;
create trigger documents_immutable before update or delete on public.documents for each row execute function private.freeze_record();
create trigger document_versions_immutable before update or delete on public.document_versions for each row execute function private.freeze_record();
create trigger decisions_immutable before update or delete on public.case_decisions for each row execute function private.freeze_record();
create trigger ledger_immutable before update or delete on public.treasury_entries for each row execute function private.freeze_record();
create function private.enrich_report() returns trigger language plpgsql security definer set search_path='' as $$declare categories jsonb; agencies jsonb; line record;begin
 if not private.treasury_read() then raise exception 'forbidden' using errcode='42501';end if;
 select coalesce(jsonb_agg(jsonb_build_object('code',q.code,'kind',q.kind,'amount',q.total::text)),'[]') into categories from (select b.code,e.kind,sum(e.amount::numeric*e.direction) total from public.treasury_entries e join public.budget_categories b on b.id=e.category_id where e.period_id=new.period_id group by b.code,e.kind order by b.code,e.kind)q;
 select coalesce(jsonb_agg(jsonb_build_object('organization',q.short_name,'cash_expense',q.total::text)),'[]') into agencies from (select o.short_name,sum(e.amount) total from public.treasury_entries e join public.financial_cases c on c.id=e.case_id join public.organizations o on o.id=c.organization_id where e.period_id=new.period_id and e.kind='EXPENSE' group by o.short_name order by o.short_name)q;
 new.snapshot:=new.snapshot||jsonb_build_object('categories',categories,'organizations',agencies);
 new.content_hash:=encode(sha256(convert_to(new.snapshot::text,'UTF8')),'hex');
 new.bbcode:=new.bbcode||chr(10)||chr(10)||'[b]Разрез статей (знак отражает направление движения)[/b]';
 for line in select * from jsonb_to_recordset(categories) as x(code text,kind text,amount text) loop new.bbcode:=new.bbcode||chr(10)||replace(replace(line.code,'[','('),']',')')||' · '||line.kind||': $'||line.amount;end loop;
 new.bbcode:=new.bbcode||chr(10)||chr(10)||'[b]Кассовые расходы по ведомствам[/b]';
 for line in select * from jsonb_to_recordset(agencies) as x(organization text,cash_expense text) loop new.bbcode:=new.bbcode||chr(10)||replace(replace(line.organization,'[','('),']',')')||': $'||line.cash_expense;end loop;
 return new;
end;$$;
create trigger enrich_report before insert on public.public_report_drafts for each row execute function private.enrich_report();
revoke all on function private.freeze_record(),private.enrich_report() from public,anon,authenticated;
create policy sequences_denied on public.document_sequences for select to authenticated using(false);
commit;
